from abc import ABC, abstractmethod


class Thing(ABC):
    unit = "шт."  # атрибут класу

    def __init__(self, name, qty=0):
        self.name = name  # публічне
        self._qty = qty  # внутрішнє

    @property
    def qty(self):  # лише читати
        return self._qty

    @abstractmethod
    def describe(self): ...

    @classmethod
    def from_row(cls, row):  # фабрика
        name, qty = row.split(";")
        return cls(name, int(qty))


class Item(Thing):  # успадкування
    def describe(self):  # своя версія
        return f"{self.name}: {self.qty}"

    def __str__(self):
        return self.describe()


