class Item:
    def __init__(self, name, qty=0):
        self.name = name
        self._qty = 0
        self.receive(qty)

    @property
    def qty(self):
        return self._qty

    def receive(self, n):
        if n < 0:
            raise ValueError("Мінус?")
        self._qty += n

    def issue(self, n):
        if n > self._qty:
            raise ValueError("Не вистачає")
        self._qty -= n


