from abc import ABC, abstractmethod


class Report(ABC):
    def __init__(self, items):
        self.items = items

    @abstractmethod
    def row(self, item): ...

    def render(self):
        return "\n".join(
            self.row(i) for i in self.items)


class TextReport(Report):
    def row(self, item):
        return f"{item.name} — {item.qty}"


class CsvReport(Report):
    def row(self, item):
        return f"{item.name};{item.qty}"

